include('../config.php');require_once __DIR__.'/../base/NotificationPolicy.class.php';require_once __DIR__.'/../base/ResourcePolicy.class.php';require_once __DIR__.'/../base/WormholePolicy.class.php';$pagegen=new page_gen();$pagegen->round_to=4;$pagegen->start();$game=new Game();if(!$game->loggedIn||!isset($_GET['time'])){header('Location: ../index.php');exit;}$db=$game->db_link;$uid=(int)$_SESSION['userid'];NotificationPolicy::ensureTable($db);$db->query("CREATE TABLE IF NOT EXISTS wormhole_signatures(signature_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,uid INT NOT NULL,signature_code VARCHAR(24) NOT NULL,wormhole_class VARCHAR(20) NOT NULL,scan_difficulty INT UNSIGNED NOT NULL DEFAULT 25,stability INT UNSIGNED NOT NULL DEFAULT 50,status VARCHAR(16) NOT NULL DEFAULT 'detected',discovered_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at DATETIME NOT NULL,PRIMARY KEY(signature_id),UNIQUE KEY uq_wormhole_signature(uid,signature_code),KEY idx_wormhole_scan_queue(uid,status,expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$db->query("CREATE TABLE IF NOT EXISTS wormhole_expeditions(expedition_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,signature_id BIGINT UNSIGNED NOT NULL,uid INT NOT NULL,scan_strength INT UNSIGNED NOT NULL,dark_matter_cost BIGINT UNSIGNED NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'enroute',dispatched_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,resolves_at DATETIME NOT NULL,outcome VARCHAR(40) NULL,reward_dark_matter BIGINT UNSIGNED NOT NULL DEFAULT 0,reward_exotic_matter BIGINT UNSIGNED NOT NULL DEFAULT 0,reward_tritanium BIGINT UNSIGNED NOT NULL DEFAULT 0,resolved_at DATETIME NULL,PRIMARY KEY(expedition_id),UNIQUE KEY uq_wormhole_active(signature_id,status),KEY idx_wormhole_due(status,resolves_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$db->query("ALTER TABLE wormhole_expeditions ADD COLUMN IF NOT EXISTS stability_at_dispatch INT UNSIGNED NOT NULL DEFAULT 50, ADD COLUMN IF NOT EXISTS elapsed_minutes INT UNSIGNED NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS collapse_risk INT UNSIGNED NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS exotic_tier INT UNSIGNED NOT NULL DEFAULT 1");if(empty($_SESSION['wormhole_csrf']))$_SESSION['wormhole_csrf']=bin2hex(random_bytes(24));$csrf=$_SESSION['wormhole_csrf'];$h=static fn($v):string=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$notice='';$error='';$db->query("INSERT IGNORE INTO hyperspace_systems(uid) VALUES($uid)");$db->query("INSERT IGNORE INTO player_resources(uid) VALUES($uid)");$res=($q=$db->query("SELECT dark_matter,exotic_matter,tritanium FROM player_resources WHERE uid=$uid LIMIT 1"))?$q->fetch_assoc():[];$sys=($q=$db->query("SELECT wormhole_scan_cooldown_at,jump_gate_level,stargate_level,hyperspace_core_level FROM hyperspace_systems WHERE uid=$uid LIMIT 1"))?$q->fetch_assoc():[];
if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??'')))$error='Security validation failed.';else{$action=(string)($_POST['wormhole_action']??'');try{if($action==='scan'){$now=time();$cooldown=strtotime((string)($sys['wormhole_scan_cooldown_at']??''));if($cooldown&&$cooldown>$now)throw new RuntimeException('Scanner cooldown active for '.($cooldown-$now).' seconds.');$cost=25+((int)($sys['hyperspace_core_level']??0)*5);$balance=(int)($res['dark_matter']??0);if($balance<$cost)throw new RuntimeException('Insufficient Dark Matter for a wormhole scan.');$difficulty=random_int(20,85);$class=['stable','unstable','ancient','null','quantum'][random_int(0,4)];$code='WH-'.strtoupper(bin2hex(random_bytes(4)));$stability=random_int(25,95);$expires=date('Y-m-d H:i:s',$now+86400);$db->begin_transaction();$ok=$db->query("UPDATE player_resources SET dark_matter=dark_matter-$cost WHERE uid=$uid AND dark_matter>=$cost LIMIT 1");$st=$db->prepare("INSERT INTO wormhole_signatures(uid,signature_code,wormhole_class,scan_difficulty,stability,expires_at) VALUES(?,?,?,?,?,?)");$st->bind_param('isssis',$uid,$code,$class,$difficulty,$stability,$expires);if(!$ok||$db->affected_rows!==1||!$st->execute())throw new RuntimeException('Wormhole scan could not be recorded.');$next=date('Y-m-d H:i:s',$now+max(60,300-((int)($sys['jump_gate_level']??0)*15)));$db->query("UPDATE hyperspace_systems SET wormhole_scan_cooldown_at='$next' WHERE uid=$uid LIMIT 1");NotificationPolicy::push($db,$uid,'wormhole_scan','Wormhole signature detected','Scanner detected '.$class.' signature '.$code.'. Exploration risk: '.$difficulty.'.','wormhole:scan:'.$code,['signature_code'=>$code,'class'=>$class]);$db->commit();$notice='Signature '.$code.' detected. Scan strength '.$stability.'.';}
elseif($action==='explore'){$sig=(int)($_POST['signature_id']??0);$row=$db->query("SELECT * FROM wormhole_signatures WHERE signature_id=$sig AND uid=$uid AND status='detected' AND expires_at>NOW() FOR UPDATE");$signature=$row?$row->fetch_assoc():null;if(!$signature)throw new RuntimeException('Wormhole signature is unavailable or expired.');$active=$db->query("SELECT expedition_id FROM wormhole_expeditions WHERE uid=$uid AND status='enroute' LIMIT 1");if($active&&$active->num_rows)throw new RuntimeException('An exploration probe is already in transit.');$cost=50+((int)$signature['scan_difficulty']*3);$balance=(int)($res['dark_matter']??0);if($balance<$cost)throw new RuntimeException('Insufficient Dark Matter to launch this probe.');$stabilityAtDispatch=(int)$signature['stability'];$strength=$stabilityAtDispatch+((int)($sys['hyperspace_core_level']??0)*4)+((int)($sys['stargate_level']??0)*3);$etaSeconds=max(60,180-((int)($sys['jump_gate_level']??0)*12));$elapsedMinutes=max(1,(int)ceil($etaSeconds/60));$collapseRisk=WormholePolicy::collapseRisk($stabilityAtDispatch,(int)$signature['scan_difficulty'],(string)$signature['wormhole_class'],$elapsedMinutes);$exoticTier=WormholePolicy::exoticTier((int)$signature['scan_difficulty'],$collapseRisk);$eta=date('Y-m-d H:i:s',time()+$etaSeconds);$db->begin_transaction();$ok=$db->query("UPDATE player_resources SET dark_matter=dark_matter-$cost WHERE uid=$uid AND dark_matter>=$cost LIMIT 1");$st=$db->prepare('INSERT INTO wormhole_expeditions(signature_id,uid,scan_strength,dark_matter_cost,resolves_at,stability_at_dispatch,elapsed_minutes,collapse_risk,exotic_tier) VALUES(?,?,?,?,?,?,?,?,?)');$st->bind_param('iiiisiiii',$sig,$uid,$strength,$cost,$eta,$stabilityAtDispatch,$elapsedMinutes,$collapseRisk,$exoticTier);if(!$ok||$db->affected_rows!==1||!$st->execute())throw new RuntimeException('Exploration dispatch failed.');$db->query("UPDATE wormhole_signatures SET status='explored' WHERE signature_id=$sig AND uid=$uid AND status='detected'");NotificationPolicy::push($db,$uid,'wormhole_expedition','Wormhole probe launched','Probe en route to '.$signature['signature_code'].'; resolution ETA '.$eta.'.','wormhole:launch:'.$sig);$db->commit();$notice='Probe launched toward '.$signature['signature_code'].'. ETA '.$eta.'.';}}
catch(Throwable $e){$db->rollback();$error=$e->getMessage()?:'Wormhole action failed.';}$res=($q=$db->query("SELECT dark_matter,exotic_matter,tritanium FROM player_resources WHERE uid=$uid LIMIT 1"))?$q->fetch_assoc():$res;$sys=($q=$db->query("SELECT wormhole_scan_cooldown_at,jump_gate_level,stargate_level,hyperspace_core_level FROM hyperspace_systems WHERE uid=$uid LIMIT 1"))?$q->fetch_assoc():$sys;}}
$signatures=$db->query("SELECT * FROM wormhole_signatures WHERE uid=$uid AND status='detected' AND expires_at>NOW() ORDER BY discovered_at DESC LIMIT 30");$history=$db->query("SELECT * FROM wormhole_expeditions WHERE uid=$uid ORDER BY expedition_id DESC LIMIT 20");echo '<div class="comm-shell wormhole-console"><div class="page-hub-head"><span class="rts-kicker">UNIVERSE CIVILIZATION // DEEP SPACE EXPLORATION</span><h3>Wormhole Scanner and Exploration</h3><p>Spend Dark Matter to detect signatures, assess instability, and launch probes into unknown transit corridors.</p></div>';if($notice)echo '<div class="comm-alert">'.$h($notice).'</div>';if($error)echo '<div class="comm-alert comm-error">'.$h($error).'</div>';echo '<section class="comm-card"><h4>Scanner Status</h4><p>Dark Matter: <strong>'.number_format((int)($res['dark_matter']??0)).'</strong> · Exotic Matter: <strong>'.number_format((int)($res['exotic_matter']??0)).'</strong> · Tritanium: <strong>'.number_format((int)($res['tritanium']??0)).'</strong></p><form method="post" action="/modules/wormholes.php?time='.time().'" class="inline-form"><input type="hidden" name="csrf" value="'.$h($csrf).'"/><input type="hidden" name="wormhole_action" value="scan"/><button class="comm-btn">Scan for Wormhole Signatures</button></form><p class="market-note">Scan cost begins at 25 Dark Matter. Exploration costs 50 Dark Matter plus signature difficulty.</p></section><section class="comm-card"><h4>Detected Signatures</h4><div class="admin-table-wrap"><table><tr><th>Code</th><th>Class</th><th>Difficulty</th><th>Stability</th><th>Expires</th><th>Action</th></tr>';if($signatures)while($s=$signatures->fetch_assoc())echo '<tr><td>'.$h($s['signature_code']).'</td><td>'.$h(ucfirst($s['wormhole_class'])).'</td><td>'.(int)$s['scan_difficulty'].'</td><td>'.(int)$s['stability'].'</td><td>'.$h($s['expires_at']).'</td><td><form method="post" action="/modules/wormholes.php?time='.time().'" class="inline-form"><input type="hidden" name="csrf" value="'.$h($csrf).'"/><input type="hidden" name="wormhole_action" value="explore"/><input type="hidden" name="signature_id" value="'.(int)$s['signature_id'].'"/><button class="comm-btn">Launch Probe</button></form></td></tr>';echo '</table></div></section><section class="comm-card"><h4>Exploration History</h4><div class="admin-table-wrap"><table><tr><th>Expedition</th><th>Strength</th><th>Risk</th><th>Exotic Tier</th><th>Status</th><th>Outcome</th><th>Dark Matter</th><th>Exotic Matter</th><th>Tritanium</th><th>Resolved</th></tr>';if($history)while($e=$history->fetch_assoc())echo '<tr><td>#'.(int)$e['expedition_id'].'</td><td>'.(int)$e['scan_strength'].'</td><td>'.(int)$e['collapse_risk'].'%</td><td>Tier '.(int)$e['exotic_tier'].'</td><td>'.$h($e['status']).'</td><td>'.$h($e['outcome']??'Pending').'</td><td>'.number_format((int)$e['reward_dark_matter']).'</td><td>'.number_format((int)$e['reward_exotic_matter']).'</td><td>'.number_format((int)$e['reward_tritanium']).'</td><td>'.$h($e['resolved_at']??$e['resolves_at']).'</td></tr>';echo '</table></div></section></div>';$pagegen->stop();print('page generation time: '.$pagegen->gen());?>
